// reminders only, not coaching or medical advice.
export const EXINFO={"Squats": {"what": "A bodyweight or loaded squat, sitting the hips down between the knees and standing back up; trains quads, glutes and hips.","aka": ["squat","back squat","air squat","bodyweight squat"]},"Forward lunges": {"what": "Stepping forward into a lunge and pushing back to standing; trains quads, glutes and balance.","aka": ["lunge","front lunge","forward lunge"]},"Backward lunges": {"what": "Stepping back into a lunge and returning to standing; trains quads and glutes one leg at a time.","aka": ["reverse lunge","back lunge","backward lunge"]},"Bulgarian split squat": {"what": "A split squat with the back foot raised on a bench; trains quads, glutes and single-leg strength.","aka": ["BSS","rear-foot elevated split squat","RFESS","Bulgarian squat"]},"Wall sit": {"what": "Holding a seated position with the back flat against a wall; an isometric hold for the quads.","aka": ["wall squat","wall sits","chair hold"]},"Front squat": {"what": "A barbell squat with the bar across the front of the shoulders; trains quads, upper back and an upright torso.","aka": ["barbell front squat","FS"]},"Goblet squat": {"what": "A squat holding one dumbbell or kettlebell at the chest; trains quads and glutes and teaches upright squatting.","aka": ["KB goblet squat","dumbbell goblet squat"]},"Box squat": {"what": "A barbell squat sitting back to a box before standing; trains hips, glutes and drive from a dead stop.","aka": ["barbell box squat","box squats"]},"Hack squat": {"what": "A machine squat on an angled sled with the back supported; trains the quads.","aka": ["machine hack squat","hack squats","sled squat"]},"Leg press": {"what": "Pushing a weighted sled away with the legs on a machine; trains quads and glutes.","aka": ["sled leg press","45-degree leg press","machine leg press"]},"Leg extension": {"what": "A seated machine movement straightening the knees against a pad; isolates the quads.","aka": ["knee extension","quad extension","leg extensions"]},"Walking lunges": {"what": "Lunging forward step after step across the floor; trains quads, glutes and balance.","aka": ["walking lunge","lunge walk","travelling lunges"]},"Step ups": {"what": "Stepping up onto a box or bench with one leg and lowering back down; trains quads and glutes.","aka": ["step-up","box step-up","dumbbell step-up"]},"Smith machine squat": {"what": "A squat with the bar fixed on the Smith machine's guided track; trains quads and glutes.","aka": ["Smith squat"]},"Smith machine front squat": {"what": "A front squat on the Smith machine, bar across the front of the shoulders; trains the quads.","aka": ["Smith front squat"]},"Smith machine sumo squat": {"what": "A wide-stance, toes-out squat on the Smith machine; trains glutes, adductors and quads.","aka": ["Smith sumo squat","wide-stance Smith squat"]},"Smith machine split squat": {"what": "A staggered-stance split squat on the Smith machine; trains quads and glutes one leg at a time.","aka": ["Smith split squat","Smith static lunge"]},"Smith machine Bulgarian split squat": {"what": "A rear-foot elevated split squat under the Smith bar; trains quads and glutes one leg at a time.","aka": ["Smith BSS","Smith rear-foot elevated split squat"]},"Smith machine reverse lunge": {"what": "A backward lunge with the Smith bar on the back; trains quads and glutes.","aka": ["Smith reverse lunge","Smith back lunge"]},"Smith machine front lunge": {"what": "A forward lunge under the Smith bar; trains quads and glutes of the front leg.","aka": ["Smith forward lunge","Smith lunge"]},"Pistol squat": {"what": "A full single-leg squat with the free leg held straight out in front; trains leg strength, balance and mobility.","cues": ["Free leg out straight, arms reach forward","Sit down slowly over the whole standing foot","Drive up without the knee caving in"],"aka": ["pistol","single-leg squat","one-leg squat"]},"Hindu squats": {"what": "Rhythmic bodyweight squats rising onto the toes with a swing of the arms, the baithak of Indian wrestlers; builds leg endurance.","cues": ["Swing the arms back as you sit down","Let the heels rise near the bottom","Breathe in rhythm, keep a steady pace"],"aka": ["baithak","bethak","baithaks","Indian squats"]},"Kettlebell squat jump": {"what": "A jump squat holding a kettlebell; trains leg power.","cues": ["Hold the bell close at the chest","Dip quickly, then jump straight up","Land softly and sink into the next rep"],"aka": ["KB jump squat","weighted squat jump"]},"Safety bar squat": {"what": "A back squat with a cambered, padded yoke bar and front handles; trains legs and upper back with less shoulder strain.","cues": ["Hold the handles in front, elbows down","Stay tall as the bar pushes you forward","Drive up through the whole foot"],"aka": ["SSB squat","safety squat bar","yoke bar squat"]},"Overhead squat": {"what": "A squat holding a barbell locked out overhead with a wide grip; trains legs, shoulders, upper back and mobility.","cues": ["Wide grip, arms locked, bar over mid-foot","Push up into the bar as you sit","Go only as deep as the bar stays steady"],"aka": ["OHS","overhead barbell squat"]},"Barbell foot press": {"what": "An old-time leg press: lying on the back and pressing a barbell up on the soles of the feet; trains the legs.","cues": ["Have a partner or supports place the bar","Lower the knees toward the chest slowly","Press to straight legs, bar kept level"],"aka": ["foot press","lying leg press","old-time leg press"]},"Quarter squat": {"what": "A short-range squat down about a quarter of full depth, often heavy; trains strength at the top of the squat.","cues": ["Brace hard before you unrack","Dip to about quarter depth, no deeper","Drive up fast to standing tall"],"aka": ["partial squat","1/4 squat"]},"Horse stance": {"what": "A held wide-legged squat with thighs near level, the ma bu of Chinese martial arts; builds leg endurance and posture.","cues": ["Feet wide and parallel, knees pushed out","Sink toward thighs level, back upright","Breathe low and steady through the hold"],"aka": ["ma bu","mabu","horse riding stance","kiba-dachi"]},"Isometric rack squat": {"what": "Pushing up with a squat into a bar fixed under power-rack pins and holding; builds squat strength at a chosen angle.","cues": ["Set the pins at the angle you want","Brace, then drive up into the pins hard","Hold 6–12 seconds, then ease off"],"aka": ["isometric squat","rack isometric squat","functional isometric squat"]},"Deadlift": {"what": "Lifting a loaded barbell from the floor to standing by driving the hips and legs; trains the whole back chain and grip.","aka": ["conventional deadlift","barbell deadlift","DL"]},"Romanian deadlift": {"what": "A hinge lowering the bar from standing down the thighs with soft knees; trains hamstrings and glutes.","aka": ["RDL","Romanian DL","RDLs"]},"Kettlebell swings": {"what": "A hip hinge snapping a kettlebell from between the legs to chest height; trains glutes, hamstrings and conditioning.","aka": ["KB swing","Russian swing","two-hand swing","kettlebell swing"]},"Kettlebell deadlift": {"what": "Lifting a kettlebell from between the feet to standing; teaches the hip hinge and trains the back chain.","aka": ["KB deadlift"]},"Single-leg RDL": {"what": "A Romanian deadlift on one leg while the other reaches back; trains hamstrings, glutes and balance.","aka": ["SLRDL","single-leg Romanian deadlift","one-leg RDL","SL RDL"]},"Good mornings": {"what": "A hinge with a bar on the upper back, bowing forward and standing back up; trains hamstrings and lower back.","aka": ["good morning","barbell good morning"]},"Glute bridge": {"what": "Lying on the back and lifting the hips off the floor; trains the glutes and hamstrings.","aka": ["hip bridge","floor bridge","bridge"]},"Hip thrust": {"what": "Driving the hips up with the upper back on a bench, often under a loaded bar; trains the glutes.","aka": ["barbell hip thrust","hip thrusts","bench hip thrust"]},"Cable pull-through": {"what": "A hinge pulling a rope from a low cable back through the legs to standing; trains glutes and hamstrings.","aka": ["pull-through","rope pull-through"]},"Trap bar deadlift": {"what": "A deadlift standing inside a hexagonal bar with side handles; trains legs and back with a more upright torso.","aka": ["hex bar deadlift","trap bar DL","hex bar"]},"Sumo deadlift": {"what": "A wide-stance deadlift with the hands inside the knees; trains glutes, adductors, legs and back.","aka": ["sumo DL","sumo pull"]},"Rack pull": {"what": "A deadlift from pins set near the knees; trains the top of the pull, upper back and grip.","aka": ["rack pulls","partial deadlift","pin pull"]},"Back extension": {"what": "Hinging over a back-extension bench and rising to a straight line; trains lower back, glutes and hamstrings.","aka": ["hyperextension","45-degree back extension","hypers","Roman chair back extension"]},"Lying leg curl": {"what": "Lying face down on a machine, curling the heels toward the glutes; trains the hamstrings.","aka": ["prone leg curl","hamstring curl","leg curl"]},"Seated leg curl": {"what": "A seated machine curl pulling the heels down and under; trains the hamstrings.","aka": ["seated hamstring curl","leg curl"]},"Stiff-leg deadlift": {"what": "A deadlift with the legs nearly straight, lowering the bar toward the floor; trains hamstrings and lower back.","cues": ["Knees soft but nearly straight","Hinge with a long, flat back","Lower only as far as the back stays flat"],"aka": ["SLDL","stiff-legged deadlift","straight-leg deadlift"]},"Standing leg curl": {"what": "Curling one heel up behind you on a standing machine or cable; trains the hamstrings one leg at a time.","cues": ["Stand tall, hips against the pad","Curl the heel toward the glute","Lower slowly to almost straight"],"aka": ["standing hamstring curl","single-leg leg curl","cable leg curl"]},"Reverse hyper": {"what": "Lying face down on a high bench and swinging the legs up behind; trains glutes, hamstrings and lower back.","cues": ["Hips on the edge, grip the handles","Raise the legs to body level with the glutes","Lower under control, don't let them crash"],"aka": ["reverse hyperextension","reverse hypers"]},"Snatch pull": {"what": "Pulling a barbell from the floor with a snatch-width grip to full extension, without the catch; builds snatch strength.","cues": ["Wide grip, hips set, back flat","Push the floor away, bar close","Finish tall on the toes with a shrug"],"aka": ["snatch-grip pull","snatch pulls"]},"Clean pull": {"what": "Pulling a barbell from the floor with a clean grip to full extension, without the catch; builds clean strength.","cues": ["Clean grip, shoulders over the bar","Bar stays close as it passes the knees","Finish tall on the toes with a shrug"],"aka": ["clean pulls","clean-grip pull"]},"Deadlift from blocks": {"what": "A deadlift with the plates raised on blocks, shortening the pull; trains lockout strength.","cues": ["Blocks stable and level under the plates","Brace and take the slack out first","Finish tall without leaning back"],"aka": ["block pull","block deadlift","elevated deadlift"]},"Axle deadlift": {"what": "A deadlift with a thick, non-rotating axle bar; trains the pull and grip hard.","cues": ["Double overhand or mixed grip, squeeze hard","Bar close, push the floor away","Lock out tall, lower under control"],"aka": ["axle DL","thick-bar deadlift","fat bar deadlift"]},"Jefferson lift": {"what": "An old-time deadlift straddling the bar, one hand in front of the body and one behind; trains legs, back and grip.","cues": ["Straddle the bar, feet wide and turned out","One hand in front, one behind","Stand straight up without twisting"],"aka": ["straddle lift","straddle deadlift","Jefferson deadlift"]},"Hand-and-thigh lift": {"what": "An old-time short-range lift, the hands pressing the bar to the thighs as the legs straighten; moves very heavy weights.","cues": ["Bar at the thighs, hands pinning it there","Knees slightly bent, back upright and braced","Straighten the legs a few inches, then lower"],"aka": ["hand and thigh lift","old-time partial lift"]},"Isometric rack pull": {"what": "Pulling a bar up into fixed power-rack pins and holding; builds pulling strength at a chosen height.","cues": ["Set the pins where you want the hold","Brace, then pull into the pins hard","Hold 6–12 seconds without jerking"],"aka": ["isometric pull","isometric deadlift","rack isometric pull"]},"Push ups": {"what": "Lowering the chest to the floor and pressing back up with the body straight; trains chest, shoulders and triceps.","aka": ["push-up","pushup","press-up"]},"Pike push ups": {"what": "A push-up with the hips high, lowering the head toward the floor; trains the shoulders.","aka": ["pike push-up","pike press"]},"Dips": {"what": "Lowering and pressing the body between parallel bars; trains chest, triceps and shoulders.","aka": ["dip","parallel bar dip","chest dip","tricep dip"]},"Shoulder press": {"what": "Pressing a weight from the shoulders to straight overhead; trains shoulders and triceps.","aka": ["OHP","overhead press","military press","strict press"]},"Bench press": {"what": "Pressing a barbell from the chest while lying on a flat bench; trains chest, shoulders and triceps.","aka": ["bench","barbell bench press","flat bench","BP"]},"Inclined Bench Press": {"what": "A barbell bench press on an inclined bench; trains the upper chest and shoulders.","aka": ["incline bench press","incline bench","incline barbell press"]},"Decline bench press": {"what": "A barbell bench press on a decline bench; trains the lower chest and triceps.","aka": ["decline bench","decline press"]},"Dumbbell bench press": {"what": "A bench press with a dumbbell in each hand; trains chest, shoulders and triceps.","aka": ["DB bench press","dumbbell press","DB press"]},"Incline dumbbell press": {"what": "Pressing dumbbells on an inclined bench; trains the upper chest and shoulders.","aka": ["incline DB press","incline dumbbell bench"]},"Dumbbell fly": {"what": "Lying on a bench, opening the arms wide with dumbbells and hugging them back together; trains the chest.","aka": ["DB fly","dumbbell flye","chest fly","flyes"]},"Incline fly": {"what": "A dumbbell fly on a low incline bench; trains the upper chest.","aka": ["incline dumbbell fly","incline flye"]},"Cable Fly Lower": {"what": "A cable fly sweeping the hands from high to low; trains the lower chest.","aka": ["high-to-low cable fly","decline cable fly","cable crossover high to low"]},"Cable Fly Upper": {"what": "A cable fly sweeping the hands from low to high; trains the upper chest.","aka": ["low-to-high cable fly","incline cable fly"]},"Cable chest press": {"what": "A standing press pushing cable handles forward from the chest; trains chest, shoulders and triceps.","aka": ["standing cable press","cable press"]},"Cable lateral raise": {"what": "Raising a low cable handle out to the side; trains the side deltoid.","aka": ["cable side raise","single-arm cable lateral raise","cable lateral"]},"Cable Tricep Extension": {"what": "Straightening the arms against a cable, usually overhead; trains the triceps.","aka": ["overhead cable extension","cable overhead tricep extension","cable triceps extension"]},"Cable tricep pushdown": {"what": "Pushing a bar or rope down from a high cable with the elbows pinned; trains the triceps.","aka": ["pushdown","tricep pushdown","rope pushdown","triceps pressdown"]},"Dumbbell pullover": {"what": "Lowering a dumbbell behind the head and pulling it back over the chest while lying on a bench; trains lats, chest and rib cage.","cues": ["Hold one bell with both hands over the chest","Lower behind the head with soft elbows","Breathe in going down, pull back over"],"aka": ["DB pullover","pullover","straight-arm pullover"]},"Behind-the-neck press": {"what": "Pressing a barbell overhead from behind the neck; trains shoulders and upper back and needs good shoulder mobility.","cues": ["Grip wider than for a front press","Lower only as far as the shoulders stay easy","Press straight up, head slightly forward"],"aka": ["BTN press","press behind neck","behind the neck press"]},"Dumbbell lateral raise": {"what": "Raising dumbbells out to the sides to shoulder height; trains the side deltoids.","cues": ["Slight bend in the elbows, slight forward lean","Lead with the elbows out to the side","Stop at shoulder height, lower slowly"],"aka": ["lateral raise","side raise","lat raise","side lateral raise"]},"Front raise": {"what": "Raising a weight straight out in front to shoulder height; trains the front deltoids.","cues": ["Arms nearly straight, stand tall","Lift to shoulder height without swinging","Lower slowly under control"],"aka": ["front delt raise","dumbbell front raise","plate front raise"]},"Single-arm dumbbell press": {"what": "Pressing one dumbbell overhead at a time; trains the shoulder and the trunk against tilting.","cues": ["Brace and stand tall, don't lean away","Press straight up beside the head","Lower to the shoulder with control"],"aka": ["one-arm dumbbell press","single-arm DB press","one-arm shoulder press"]},"Skull crusher": {"what": "Lying on a bench, bending the elbows to lower a bar toward the forehead and extending back up; trains the triceps.","cues": ["Upper arms angled slightly back and fixed","Lower the bar toward the forehead slowly","Straighten the arms without flaring the elbows"],"aka": ["lying tricep extension","skullcrusher","lying triceps extension","French press"]},"Overhead tricep extension": {"what": "Lowering a weight behind the head with both hands and straightening the arms overhead; trains the triceps.","cues": ["Elbows point up and stay close","Lower behind the head to a full stretch","Straighten the arms fully overhead"],"aka": ["overhead triceps extension","French press","dumbbell overhead extension"]},"Single-arm overhead tricep extension": {"what": "An overhead tricep extension with one dumbbell in one hand; trains each triceps on its own.","cues": ["Elbow points up beside the head","Lower the bell behind the head slowly","Straighten the arm fully, ribs down"],"aka": ["one-arm overhead extension","single-arm French press","one-arm tricep extension"]},"Rolling dumbbell tricep extension": {"what": "Lying on a bench, lowering dumbbells beside the head, rolling the elbows back, then forward to press; trains the triceps.","cues": ["Lower the bells beside the head","Let the elbows roll back, then forward","Press to straight arms over the chest"],"aka": ["rolling DB extension","rolling triceps extension"]},"Floor press": {"what": "A bench press lying on the floor, so the elbows stop at the ground; trains lockout strength and triceps.","cues": ["Lie with knees bent or legs straight","Lower until the upper arms touch the floor","Pause briefly, then press up"],"aka": ["barbell floor press","dumbbell floor press"]},"Pec deck": {"what": "A seated machine bringing padded arms or handles together in front of the chest; trains the chest.","cues": ["Set the seat so the handles meet chest height","Bring the arms together with soft elbows","Return slowly to a stretch you own"],"aka": ["pec dec","machine fly","butterfly","chest fly machine"]},"Cable crossover": {"what": "Standing between two high cables and sweeping the handles together in front; trains the chest.","cues": ["Stagger the feet, slight forward lean","Soft, fixed elbows throughout","Bring the hands together, return slowly"],"aka": ["cable cross","cable fly","crossovers"]},"Smith machine shoulder press": {"what": "Pressing a Smith machine bar overhead from the shoulders, seated or standing; trains shoulders and triceps.","cues": ["Bench placed so the bar clears the face","Lower to about chin height","Press up without locking hard"],"aka": ["Smith shoulder press","Smith overhead press","Smith military press"]},"Hindu push-ups": {"what": "A flowing push-up swooping from a hips-high pike down and up into an arched back; the dand of Indian wrestlers.","cues": ["Start in a pike, hips high, arms straight","Swoop the chest low past the hands","Push up into an arch, then back to pike"],"aka": ["dand","dands","danda","Hindu push-up","dive bomber"]},"Shena push-ups": {"what": "Push-ups on the zurkhaneh's low wooden board, done in long rhythmic sets to the drum; trains chest, shoulders and endurance.","cues": ["Hands on the board, body long and straight","Keep the rhythm steady with the group","Lower under control, press fully up"],"aka": ["shena","shenow","zurkhaneh push-ups","Persian push-ups"]},"Persian meels": {"what": "Swinging heavy wooden clubs, one in each hand, around and behind the shoulders in the zurkhaneh; trains shoulders, grip and trunk.","cues": ["Start light, club close to the body","Swing behind the shoulder, then over and out","Keep the trunk upright and braced"],"aka": ["meel","mil","meels","Persian clubs","Persian club swinging"]},"Kabbadeh": {"what": "Shaking an iron bow strung with a heavy chain overhead from side to side, a zurkhaneh drill; trains shoulders, arms and trunk.","cues": ["Hold the bow overhead, arms nearly straight","Shift it side to side in rhythm","Brace the trunk, don't arch the lower back"],"aka": ["kabadeh","kaman","zurkhaneh bow"]},"Sang press": {"what": "Lying on the back pressing a pair of heavy wooden shields, rolling side to side; a zurkhaneh drill for chest, shoulders and arms.","cues": ["Lie flat, a shield upright in each hand","Press one up as you roll toward the other","Lower each shield under control"],"aka": ["sang","sang gereftan","Persian shields"]},"Kettlebell press": {"what": "Pressing a kettlebell from the rack position to overhead; trains shoulders, triceps and trunk.","cues": ["Bell in the rack, wrist straight","Squeeze the glutes and press straight up","Lower back to the rack with control"],"aka": ["KB press","kettlebell military press","kettlebell overhead press"]},"Bridge press": {"what": "Pressing a weight up from the chest while held in a wrestler's bridge, an old-time drill; trains neck, back and pressing.","cues": ["Build up the bridge without weight first","Press from the chest, hips held high","Keep the weight light and the neck steady"],"aka": ["wrestler's bridge press","bridging press","bridge pullover and press"]},"Push press": {"what": "An overhead press driven by a short dip and drive of the legs; trains shoulders, triceps and power.","cues": ["Dip straight down a few inches, heels down","Drive hard with the legs into the press","Lock out overhead, head through"],"aka": ["barbell push press","PP"]},"Seated press": {"what": "A shoulder press done sitting on a bench; trains shoulders and triceps without help from the legs.","cues": ["Sit tall, back upright or on the pad","Press straight up, head through at the top","Lower to chin height with control"],"aka": ["seated shoulder press","seated overhead press","seated military press"]},"Log press": {"what": "A strongman lift cleaning a thick log by its neutral handles to the chest and pressing it overhead; trains shoulders and trunk.","cues": ["Roll the log up the body to the chest","Elbows high, then dip and drive","Lock out with the head through"],"aka": ["log clean and press","strongman log"]},"Incline log press": {"what": "Pressing a strongman log from the chest while lying on an incline bench; trains upper chest and shoulders.","cues": ["Back set into the incline bench","Lower the log to the upper chest","Press up in a smooth line"],"aka": ["incline log bench"]},"Axle press": {"what": "Cleaning and pressing a thick, non-rotating axle bar overhead; trains shoulders, triceps and grip.","cues": ["Clean the axle up to the shoulders","Brace, then press or dip and drive","Lock out with the head through"],"aka": ["axle clean and press","thick-bar press","fat bar press"]},"Barbell pullover": {"what": "Lying on a bench, lowering a barbell behind the head on near-straight arms and pulling it back over; trains lats and rib cage.","cues": ["Narrow grip, arms nearly straight","Lower behind the head as you breathe in","Pull back over the chest, ribs down"],"aka": ["straight-arm pullover","lying pullover","bent-arm pullover"]},"Bent press": {"what": "An old-time one-arm lift: bend sideways and down under the weight until the arm is locked overhead, then stand.","cues": ["Start light, eyes on the weight","Lean away and screw the body under it","Stand up with the arm locked straight"],"aka": ["bent-press","Saxon bent press","screw press"]},"One-hand barbell press": {"what": "Pressing a barbell overhead with one hand; trains the shoulder, grip and balance.","cues": ["Grip at the centre so the bar balances","Brace and press straight up","Lower slowly, keep the bar level"],"aka": ["one-arm barbell press","single-arm barbell press"]},"One-arm push": {"what": "An old-time one-hand lift, pushing a weight up from the shoulder while leaning under it, more upright than the bent press.","cues": ["Weight at the shoulder, elbow on the hip","Lean slightly away as you push","Lock the arm and stand tall"],"aka": ["one-hand push","side press","one-arm side press"]},"Fingertip push-ups": {"what": "Push-ups on the fingertips instead of the palms; trains the fingers, hands and pushing strength.","cues": ["Fingers spread and slightly bent","Body in one straight line","Lower only as far as the fingers hold"],"aka": ["fingertip push-up","finger push-ups"]},"Handstand": {"what": "Balancing upside down on the hands, against a wall or freestanding; trains shoulders, balance and body control.","cues": ["Hands shoulder width, fingers spread","Push the floor away, arms locked","Squeeze the legs together, ribs in"],"aka": ["handstand hold","wall handstand"]},"Scrum machine": {"what": "Driving against a rugby scrum sled in the bound scrummaging position; trains legs, back and pushing as a unit.","cues": ["Hips below the shoulders, back flat","Short, powerful steps on the balls of the feet","Push together, head up"],"aka": ["scrum sled","scrummaging machine","scrum practice"]},"Self-resisted tricep extension": {"what": "Straightening one arm while the other hand resists it, an old-time drill with no equipment; trains the triceps.","cues": ["One hand pushes, the other resists","Move slowly through the full range","Keep the resistance steady both ways"],"aka": ["self-resistance tricep extension","dynamic tension tricep"]},"Handstand push-ups": {"what": "Lowering the head toward the floor in a handstand, usually against a wall, and pressing back up; trains shoulders and triceps.","cues": ["Hands just wider than the shoulders","Lower the head softly to the floor or mat","Press up to locked arms, body tight"],"aka": ["HSPU","wall handstand push-up","handstand press"]},"Isometric rack press": {"what": "Pressing a bar up into fixed power-rack pins and holding; builds pressing strength at a chosen height.","cues": ["Set the pins at the press height you want","Brace, then press into the pins hard","Hold 6–12 seconds, then ease off"],"aka": ["isometric press","rack isometric press","functional isometric press"]},"Tricep kickback": {"what": "Hinged forward, straightening the arm back behind the body with a dumbbell; trains the triceps.","cues": ["Hinge forward, upper arm along the body","Straighten the arm back fully","Lower slowly, elbow stays put"],"aka": ["dumbbell kickback","triceps kickback","kickbacks"]},"Frog stand": {"what": "Balancing on the hands with the knees resting on the backs of the elbows; trains wrists, shoulders and balance.","cues": ["Hands flat, fingers spread","Knees resting on the backs of the elbows","Lean forward slowly until the feet float"],"aka": ["crow pose","crow","bakasana"]},"Headstand": {"what": "Balancing upside down on the head and forearms or hands; trains shoulders, neck, trunk and balance.","cues": ["Most of the weight on the forearms, not the head","Rise slowly with the legs together","Come down with control"],"aka": ["sirsasana","tripod headstand"]},"Forearm stand": {"what": "Balancing upside down on the forearms; trains shoulders, upper back and balance.","cues": ["Forearms parallel, elbows shoulder width","Push the floor away, shoulders over elbows","Squeeze the legs together, ribs in"],"aka": ["pincha mayurasana","forearm balance","elbow stand"]},"One-arm push-up": {"what": "A push-up on one hand with the feet wide; trains chest, shoulder, triceps and the whole trunk.","cues": ["Feet wide, free hand behind the back","Body square to the floor, glutes tight","Lower under control and press up"],"aka": ["one-handed push-up","single-arm push-up","OAPU"]},"Pull ups": {"what": "Hanging from a bar, palms away, and pulling the chin over it; trains lats, upper back and arms.","aka": ["pull-up","pullup","chin over bar","overhand pull-up"]},"Chin ups": {"what": "A pull-up with the palms facing you; trains lats, upper back and biceps.","aka": ["chin-up","chinup","chins","underhand pull-up"]},"Gorilla rows": {"what": "Alternating kettlebell rows from a wide, hinged stance with both bells on the floor; trains the back and trunk.","aka": ["gorilla row","kettlebell gorilla row"]},"Standing kettlebell rows": {"what": "A hinged row pulling a kettlebell toward the hip; trains the upper back and lats.","aka": ["kettlebell row","KB row","bent-over kettlebell row"]},"Shoulder shrugs": {"what": "Lifting the shoulders straight up toward the ears with a weight in the hands; trains the upper traps.","aka": ["shrugs","barbell shrug","dumbbell shrug"]},"Lat pulldown": {"what": "Pulling a cable bar from overhead to the upper chest while seated; trains the lats.","aka": ["pulldown","lat pull-down","wide-grip pulldown"]},"Seated cable row": {"what": "Pulling a cable handle to the lower ribs while seated; trains the mid back and lats.","aka": ["cable row","seated row","low row"]},"Straight-arm pulldown": {"what": "Sweeping a high cable bar down to the thighs with straight arms; trains the lats.","aka": ["straight-arm lat pulldown","stiff-arm pulldown","cable pullover"]},"Bicep curls": {"what": "Curling dumbbells up by bending the elbows; trains the biceps.","aka": ["curls","dumbbell curl","biceps curl","DB curl"]},"Kettlebell bicep curl": {"what": "Curling a kettlebell by the handle; trains the biceps and grip.","aka": ["KB curl","kettlebell curl"]},"Cable bicep curl": {"what": "Curling a bar or handle from a low cable; trains the biceps under constant tension.","aka": ["cable curl"]},"Cable hammer curl": {"what": "Curling a rope from a low cable with the palms facing each other; trains biceps, brachialis and forearms.","aka": ["rope hammer curl","rope curl"]},"Cable face pull": {"what": "Pulling a rope from face height toward the face with the elbows high; trains rear delts and upper back.","aka": ["face pull","face pulls","rope face pull"]},"Bar Hangs": {"what": "Hanging from a bar with straight arms; trains grip and opens up the shoulders.","aka": ["dead hang","bar hang","passive hang","hang"]},"Barbell row": {"what": "Rowing a barbell to the lower ribs from a hinged position; trains mid back, lats and grip.","aka": ["bent-over row","BB row","Pendlay row","bent over barbell row"]},"Dumbbell row": {"what": "Rowing a dumbbell toward the hip with one hand and knee braced on a bench; trains lats and upper back.","aka": ["one-arm dumbbell row","DB row","single-arm row"]},"T-bar row": {"what": "Rowing one end of a loaded bar or a T-bar machine toward the chest; trains the mid back.","aka": ["T bar row","landmine row"]},"Chest-supported row": {"what": "Rowing dumbbells or a machine with the chest on an incline pad; trains the upper back without loading the lower back.","aka": ["seal row","incline row","chest supported dumbbell row"]},"Inverted row": {"what": "Pulling the chest up to a low bar with the body straight underneath; trains the upper back and arms.","aka": ["bodyweight row","Australian pull-up","body row","ring row"]},"Close-grip lat pulldown": {"what": "A lat pulldown with a narrow or V-handle; trains the lats and arms.","aka": ["close-grip pulldown","V-bar pulldown","narrow-grip pulldown"]},"Rear delt fly": {"what": "Hinged forward, raising dumbbells out to the sides; trains the rear delts and upper back.","aka": ["reverse fly","bent-over lateral raise","rear delt raise","reverse flye"]},"Barbell curl": {"what": "Curling a straight barbell up to the shoulders; trains the biceps.","aka": ["BB curl","standing barbell curl"]},"EZ-bar curl": {"what": "Curling an angled EZ bar; trains the biceps with an easier wrist angle.","aka": ["EZ curl","EZ bar curl","cambered bar curl"]},"Hammer curl": {"what": "Curling dumbbells with the palms facing each other; trains biceps, brachialis and forearms.","aka": ["neutral-grip curl","DB hammer curl"]},"Incline dumbbell curl": {"what": "Curling dumbbells lying back on an incline bench, arms hanging behind the body; trains the biceps in a stretch.","aka": ["incline curl"]},"Preacher curl": {"what": "Curling with the backs of the upper arms on an angled pad; trains the biceps strictly.","aka": ["Scott curl","preacher bench curl"]},"Concentration curl": {"what": "A seated one-arm curl with the elbow braced against the inner thigh; trains the biceps strictly.","aka": ["seated concentration curl"]},"Reverse curl": {"what": "Curling a bar with the palms facing down; trains the forearms and brachialis.","aka": ["overhand curl","pronated curl","reverse-grip curl"]},"Upright row": {"what": "Pulling a bar up the front of the body to chest height, elbows leading; trains the traps and shoulders.","cues": ["Grip about shoulder width or a little wider","Lead with the elbows, bar close","Stop at chest height, lower slowly"],"aka": ["barbell upright row","cable upright row"]},"Nautilus pullover": {"what": "A machine pullover, pads on the upper arms sweeping from overhead down to the waist; trains the lats.","cues": ["Seat set so the shoulders line up with the pivot","Push with the elbows, not the hands","Let the arms rise slowly to a full stretch"],"aka": ["machine pullover","pullover machine"]},"Single-arm machine row": {"what": "Rowing one handle at a time on a row machine; trains each side of the back.","cues": ["Chest against the pad, sit tall","Pull the elbow back past the body","Return slowly to a long arm"],"aka": ["one-arm machine row","unilateral machine row"]},"Barbell high pull": {"what": "Pulling a barbell explosively from the hips or floor to chest height, elbows high; trains traps, shoulders and power.","cues": ["Drive with the legs and hips first","Elbows lead high and out","Bar stays close, lower with control"],"aka": ["high pull","clean high pull","snatch high pull"]},"Wrist curl": {"what": "Curling a weight up with the wrists, forearms resting on the thighs or a bench; trains the forearm flexors.","cues": ["Forearms supported, palms up","Let the bar roll to the fingers, then curl","Move only at the wrist"],"aka": ["forearm curl","barbell wrist curl"]},"Reverse wrist curl": {"what": "Lifting a weight with the backs of the hands, forearms supported; trains the forearm extensors.","cues": ["Forearms supported, palms down","Lift the knuckles up toward you","Lower slowly, keep it light"],"aka": ["wrist extension","reverse forearm curl"]},"Rope climb": {"what": "Climbing a hanging rope hand over hand, with or without the legs; trains grip, back and arms.","cues": ["Grip high and pull with the arms","Clamp the rope with the feet to rest","Climb down hand under hand, never slide"],"aka": ["rope climbing","legless rope climb"]},"Zottman curl": {"what": "Curling with palms up, then turning the palms down to lower; trains the biceps and forearms.","cues": ["Curl up with the palms facing up","Turn the palms down at the top","Lower slowly with the palms down"],"aka": ["Zottman"]},"Rope hang": {"what": "Hanging from a vertical or thick rope; trains the grip and forearms.","cues": ["Grip the rope with both hands","Shoulders engaged, not shrugged","Breathe and hold, feet off the floor"],"aka": ["rope grip hang","towel hang"]},"Plate pinch": {"what": "Holding weight plates pinched together between the fingers and thumb; trains pinch grip.","cues": ["Smooth sides out, fingers one side, thumb other","Squeeze hard and stand tall","Hold for time, set down with control"],"aka": ["pinch grip","plate pinch hold","pinch carry"]},"Lat spread": {"what": "A muscle-control drill flaring the lats out wide from the sides; trains awareness and control of the back.","cues": ["Hands on the waist, thumbs back","Spread the lats wide, shoulders down","Hold, breathe, then relax slowly"],"aka": ["lat flare","Maxalding lat control","lat isolation"]},"Neck resistance": {"what": "Pushing the head against your own hand to the front, back and both sides; trains the neck.","cues": ["Hand on the head, neck in neutral","Push gradually into the hand and hold","Work all four directions evenly"],"aka": ["self-resisted neck","neck isometrics","manual neck resistance"]},"Self-resisted curl": {"what": "Curling one arm while the other hand resists it; a biceps drill needing no equipment.","cues": ["One hand curls, the other resists","Move slowly through the whole range","Keep the resistance steady both ways"],"aka": ["self-resistance curl","dynamic tension curl"]},"Isometric rack shrug": {"what": "Shrugging a bar up into fixed power-rack pins and holding; trains the traps and grip.","cues": ["Set the pins just above the hanging bar","Shrug straight up into the pins hard","Hold 6–12 seconds, arms long"],"aka": ["isometric shrug","rack shrug hold"]},"Finger lift": {"what": "An old-time grip feat, lifting a weight hooked to one or more fingers by a ring or strap; trains the fingers.","cues": ["Start very light, one finger at a time","Bend the knees and lift with the legs","Keep the finger hooked, lower slowly"],"aka": ["one-finger lift","finger lifting","ring lift"]},"Leverage lift": {"what": "Gripping a bar or hammer near one end and raising the far end with the wrist alone; trains the wrists and forearms.","cues": ["Grip near the end, arm by the side","Lever the far end up with the wrist","Lower slowly, keep the elbow still"],"aka": ["levering","sledgehammer lever","wrist levering"]},"Wrist roller": {"what": "Winding a weight on a cord up and down by turning a handle; trains the forearms and grip.","cues": ["Arms out in front at shoulder height","Roll the weight up, wrists in turn","Unroll slowly back down"],"aka": ["forearm roller","wrist roll"]},"Gripper closes": {"what": "Squeezing a torsion-spring hand gripper shut; trains crushing grip.","cues": ["Set the gripper deep in the hand","Squeeze it fully closed","Open slowly under control"],"aka": ["hand gripper","gripper","crush grip"]},"Plank": {"what": "Holding a straight line on the forearms and toes; trains the trunk.","aka": ["front plank","forearm plank","elbow plank"]},"Side plank": {"what": "Holding the body straight and side-on, propped on one forearm; trains the obliques and side of the trunk.","aka": ["side bridge"]},"Dead bug": {"what": "Lying on the back, lowering opposite arm and leg while the lower back stays down; trains the deep trunk.","aka": ["deadbug","dead bugs"]},"Hollow hold": {"what": "Lying on the back with arms and legs lifted in a shallow banana shape; trains the abs.","aka": ["hollow body hold","hollow body","dish hold"]},"Hanging knee raises": {"what": "Hanging from a bar and drawing the knees up toward the chest; trains abs and hip flexors.","aka": ["hanging knee raise","knee raises","knee tucks"]},"Pallof press": {"what": "Pressing a cable handle straight out from the chest while resisting the twist; trains the trunk.","aka": ["anti-rotation press","cable Pallof press"]},"Ab wheel rollout": {"what": "Rolling an ab wheel out from the knees and pulling it back; trains the abs and trunk.","aka": ["ab wheel","ab roller","rollout"]},"Mountain climbers": {"what": "Driving the knees to the chest in turn from a push-up position; trains the trunk and conditioning.","aka": ["mountain climber","climbers"]},"Cable crunch": {"what": "Kneeling and crunching down against a high cable rope; trains the abs.","aka": ["kneeling cable crunch","rope crunch"]},"Single Arm High to Low woodchop": {"what": "Pulling a high cable down and across the body with a turn of the trunk; trains the obliques.","aka": ["high-to-low woodchop","cable woodchop","woodchopper"]},"Single Arm Low to High woodchop": {"what": "Pulling a low cable up and across the body with a turn of the trunk; trains the obliques.","aka": ["low-to-high woodchop","reverse woodchop","cable lift"]},"Crunch": {"what": "Lying on the back and curling the shoulders and ribs toward the hips; trains the abs.","cues": ["Knees bent, feet flat","Curl the ribs toward the hips","Lower slowly, don't pull on the neck"],"aka": ["crunches","ab crunch"]},"Reverse crunch": {"what": "Lying on the back and curling the hips and knees up toward the chest; trains the lower abs.","cues": ["Knees bent, arms by the sides","Roll the hips up off the floor","Lower slowly without swinging"],"aka": ["reverse crunches","lying knee tuck"]},"GHD sit-up": {"what": "A sit-up on a glute-ham developer, leaning back past level and sitting up; trains the abs and hip flexors.","cues": ["Feet locked, hips just off the pad","Lean back only as far as you control","Sit up by driving the knees straight"],"aka": ["glute-ham sit-up","GHD situp"]},"Wrestler's bridge": {"what": "Arching up onto the head and feet with the hips high; trains the neck and back for wrestling.","cues": ["Build up with the hands on the floor","Roll on the forehead, not the crown","Hips high, move slowly and gently"],"aka": ["neck bridge","wrestler bridge","back bridge"]},"Side bend": {"what": "Bending sideways at the waist with a weight in one hand; trains the obliques.","cues": ["Stand tall, weight in one hand","Bend straight to the side, no twist","Rise using the opposite side"],"aka": ["dumbbell side bend","side bends","oblique bend"]},"Windmill": {"what": "Bending sideways and down toward the front foot with one arm reaching overhead; trains the trunk, hips and shoulder.","cues": ["Lock the top arm, eyes on the hand","Push the hip out and hinge down","Rise slowly, top arm stays vertical"],"aka": ["kettlebell windmill","dumbbell windmill","windmills"]},"Weighted sit-up": {"what": "A full sit-up holding a weight at the chest or behind the head; trains the abs and hip flexors.","cues": ["Feet anchored or flat","Hold the weight close at the chest","Curl up and lower slowly"],"aka": ["weighted situp","plate sit-up"]},"Bent-knee sit-up": {"what": "A sit-up with the knees bent and the feet flat; trains the abs and hip flexors.","cues": ["Knees bent, feet flat on the floor","Curl up through the spine","Lower slowly back down"],"aka": ["bent knee situp","sit-up"]},"Sit-ups": {"what": "Lying on the back and sitting all the way up; trains the abs and hip flexors.","cues": ["Feet flat or held, arms across the chest","Curl up one part of the spine at a time","Lower slowly to the floor"],"aka": ["sit-up","situp","full sit-up"]},"Deep breathing": {"what": "Slow, full breaths drawn low into the belly and ribs; trains the breathing muscles and calm control.","cues": ["Breathe in through the nose, belly and ribs widen","Exhale slowly and fully","Keep the shoulders relaxed"],"aka": ["diaphragmatic breathing","belly breathing","breathwork"]},"Abdominal vacuum": {"what": "Breathing out fully and drawing the belly in and up under the ribs; trains the deep abdominals.","cues": ["Exhale every bit of air","Pull the belly in and up under the ribs","Hold briefly, then breathe in slowly"],"aka": ["stomach vacuum","vacuum","uddiyana bandha"]},"Abdominal rolling": {"what": "Isolating the abdominal muscles and rolling them in a wave from side to side; a muscle-control drill.","cues": ["Exhale fully, hands on the thighs","Isolate the centre of the abs","Roll them side to side slowly"],"aka": ["nauli","abdominal roll","stomach rolling","Maxalding abdominal control"]},"Lying leg raise": {"what": "Lying on the back and raising straight legs up and down; trains the abs and hip flexors.","cues": ["Lower back pressed into the floor","Raise straight legs toward vertical","Lower slowly, stop before the back arches"],"aka": ["leg raise","leg raises","floor leg raise"]},"Barbell trunk twist": {"what": "Turning the trunk side to side with a bar across the shoulders; trains the obliques.","cues": ["Light bar on the upper back, feet planted","Turn from the trunk, hips steady","Move slowly, no momentum"],"aka": ["barbell twist","standing twist","bar twist"]},"Farmer carry": {"what": "Walking while holding a heavy weight in each hand; trains grip, traps, trunk and posture.","aka": ["farmer's walk","farmers walk","farmer's carry"]},"Suitcase carry": {"what": "Walking with a heavy weight in one hand only; trains the trunk against leaning, plus grip.","aka": ["one-arm carry","single-arm farmer carry","suitcase walk"]},"Turkish get-up": {"what": "Rising from lying to standing with a weight locked overhead, then reversing; trains shoulders and whole-body control.","aka": ["TGU","get-up","Turkish getup"]},"Kettlebell squat press clean": {"what": "Cleaning a kettlebell to the rack, squatting, and pressing it overhead as you stand; trains the whole body.","aka": ["KB clean squat press","kettlebell clean and press","kettlebell thruster"]},"Burpees": {"what": "Dropping to a push-up position, returning to a squat and jumping; trains the whole body and conditioning.","aka": ["burpee","squat thrust"]},"Power clean": {"what": "Pulling a barbell from the floor and catching it on the shoulders in a partial squat; trains power.","cues": ["Bar close, push the floor away","Snap the hips, shrug and pull under","Catch with high elbows, knees soft"],"aka": ["clean","barbell power clean","PC"]},"Sled drag": {"what": "Dragging a weighted sled by straps or a harness, walking forward or backward; trains the legs and conditioning.","cues": ["Lean into the straps, back flat","Short, steady, powerful steps","Keep tension on the strap throughout"],"aka": ["sled pull","prowler drag","harness drag"]},"Snatch": {"what": "Lifting a barbell from the floor to overhead in one movement with a wide grip; the Olympic lift for speed and power.","cues": ["Wide grip, bar close to the body","Drive with the legs, then pull under fast","Catch with arms locked, stand up steady"],"aka": ["barbell snatch","squat snatch","full snatch"]},"Clean and jerk": {"what": "Cleaning a barbell to the shoulders, then jerking it overhead; the two-part Olympic lift for strength and power.","cues": ["Clean to the shoulders, elbows high","Stand tall, then dip and drive","Split or push under, lock out overhead"],"aka": ["C&J","clean & jerk"]},"Indian clubs": {"what": "Swinging wooden clubs in circles around the body, from Indian and Persian traditions; trains shoulders, grip and coordination.","cues": ["Start light with a loose, firm grip","Let the club circle, guide it smoothly","Stay tall, move from the shoulders"],"aka": ["club swinging","jori","mudgar","clubbells","Indian club swinging"]},"Mace swings": {"what": "Swinging a long weighted mace behind the back and over the head, the gada of Indian wrestlers; trains shoulders, grip and trunk.","cues": ["Start light, hands together on the handle","Swing behind the back, then over and around","Brace the trunk, let the hips guide"],"aka": ["gada","steel mace","mace 360","10 to 2"]},"Pit digging": {"what": "Digging with a spade, which Galen recommended for strength; trains back, legs, arms and grip.","cues": ["Push the spade in with the foot","Lift with the legs, back flat","Switch sides often"],"aka": ["digging","shovelling"]},"Power snatch": {"what": "A snatch caught overhead in a partial squat instead of a full one; trains power and speed.","cues": ["Wide grip, bar close to the body","Extend hard, then pull under","Catch high with arms locked, feet set"],"aka": ["barbell power snatch","PS"]},"Kettlebell snatch": {"what": "Swinging a kettlebell from between the legs straight to overhead in one motion; trains power, shoulders and conditioning.","cues": ["Hike back, then snap the hips","Punch the hand through as the bell rises","Lock out softly, don't bang the wrist"],"aka": ["KB snatch"]},"Kettlebell jerk": {"what": "Driving a kettlebell from the rack to overhead with two dips of the legs; trains power and shoulders.","cues": ["Bell in the rack, elbow on the hip","Dip, drive hard, then dip under","Stand up with the arm locked"],"aka": ["KB jerk","girevoy jerk"]},"Kettlebell long cycle": {"what": "Cleaning a kettlebell to the rack and jerking it overhead, repeated for time; the girevoy sport event for endurance.","cues": ["Clean smoothly, receive in the rack","Rest in the rack, breathe each rep","Jerk overhead, then drop back to the swing"],"aka": ["long cycle","LC","kettlebell clean and jerk"]},"Depth jump": {"what": "Stepping off a box, landing and jumping straight up as fast as possible; trains reactive leg power.","cues": ["Step off, don't jump off","Land on the balls of both feet together","Rebound up as fast as you can"],"aka": ["shock jump","drop jump","depth jumps"]},"Standing long jump": {"what": "Jumping as far forward as possible from a standing two-foot start; trains leg power.","cues": ["Swing the arms back and dip","Drive forward and up with the arms","Land softly with bent knees"],"aka": ["broad jump","standing broad jump","SLJ"]},"Jerk": {"what": "Driving a barbell from the shoulders to overhead with a dip and drive, catching in a split or push; trains power.","cues": ["Dip straight down, heels flat","Drive hard and punch under the bar","Lock out, then recover the feet"],"aka": ["split jerk","push jerk","barbell jerk"]},"Hang snatch": {"what": "A snatch started with the bar hanging at the thighs or knees; trains speed and the second pull.","cues": ["Start tall, push the hips back to the hang","Jump and pull under fast","Catch with arms locked overhead"],"aka": ["hang power snatch","high hang snatch"]},"Atlas stone lift": {"what": "Lifting a round concrete stone from the ground to the lap and onto a platform; trains back, hips and grip.","cues": ["Straddle the stone, hands under it","Roll it to the lap, then re-grip","Extend the hips hard to load it"],"aka": ["atlas stones","stone loading","stone to shoulder"]},"Natural stone lift": {"what": "Lifting an unshaped natural stone from the ground, as in Scottish and Basque tradition; trains back, legs and grip.","cues": ["Find the best grip, hug it close","Lift with the legs, back braced","Set it down under control"],"aka": ["stone lifting","lifting stones","Dinnie stones","harri jasotzea"]},"Stone carry": {"what": "Carrying a heavy stone hugged to the chest for distance; trains back, legs, grip and breathing.","cues": ["Hug the stone high against the chest","Short, steady steps","Brace and breathe through the walk"],"aka": ["stone hug carry","Husafell stone carry"]},"Yoke carry": {"what": "Walking with a heavy frame across the upper back; trains legs, trunk and posture under load.","cues": ["Bar set high on the back, hands wide","Brace hard before you lift it","Short, fast, even steps"],"aka": ["yoke walk","super yoke"]},"Stone put": {"what": "Throwing a heavy stone from the shoulder for distance, a Highland games event; trains whole-body power.","cues": ["Stone tucked at the neck, elbow under it","Drive from the legs and hips","Push it out at about 45 degrees"],"aka": ["putting the stone","Braemar stone","stone throw"]},"Caber toss": {"what": "Running with a tall log held upright and tossing it to flip end over end, a Highland games event.","cues": ["Lift the caber close and balanced","Run to build speed, keep it upright","Stop, drive up and pull it over"],"aka": ["tossing the caber","caber"]},"Scottish hammer throw": {"what": "Swinging a ball on a rigid shaft round the head from fixed feet and throwing it, a Highland games event.","cues": ["Feet fixed, back to the throwing area","Wind the hammer round the head","Drive up through the legs and release"],"aka": ["Highland hammer","heavy hammer","light hammer"]},"Weight for distance": {"what": "Spinning and throwing a heavy weight on a short chain with one hand, a Highland games event.","cues": ["Swing the weight back to start","Turn on the balls of the feet","Release with the arm long, hips leading"],"aka": ["WFD","heavy weight for distance","56 lb weight throw"]},"Weight over bar": {"what": "Throwing a heavy weight one-handed up and backward over a raised bar, a Highland games event.","cues": ["Stand facing away from the bar","Swing between the legs, drive up hard","Release overhead, then step out of the way"],"aka": ["WOB","weight for height","56 lb over bar"]},"Keg toss": {"what": "Throwing a keg backward over the head onto or over a high bar, a strongman and Highland event.","cues": ["Swing the keg between the legs","Drive with the hips, arms long","Release overhead and clear the area"],"aka": ["keg throw","keg over bar"]},"Indian club front circle": {"what": "Swinging a club in a full circle in front of the body; trains the shoulders and coordination.","cues": ["Light club, loose grip","Circle in front with the arm long","Keep the body still"],"aka": ["front circle","inward circle"]},"Indian club back circle": {"what": "Swinging a club in a circle behind the shoulder and head; trains shoulder mobility.","cues": ["Light club, elbow bends behind","Drop the club behind the head","Keep the trunk upright"],"aka": ["back circle","club back swing"]},"Indian club side circle": {"what": "Swinging a club in a full circle at the side of the body; trains the shoulders and grip.","cues": ["Light club, arm long","Circle along the side of the body","Stay tall, eyes forward"],"aka": ["side circle","outside circle"]},"Indian club moulinet": {"what": "Small circles of the club turned from the wrist in front of the body; trains wrists, forearms and grip.","cues": ["Hold the club upright in front","Circle it from the wrist, not the arm","Keep the elbow soft and still"],"aka": ["moulinet","wrist circle","mill"]},"Indian club windmill": {"what": "Swinging clubs in large alternating circles like windmill sails; trains the shoulders and coordination.","cues": ["Light clubs, arms long","Alternate the circles smoothly","Stay tall, breathe in rhythm"],"aka": ["club windmill","windmills"]},"One-hand barbell clean": {"what": "Pulling a barbell from the floor to the shoulder with one hand, an old-time lift; trains grip, back and balance.","cues": ["Grip at the centre so the bar balances","Pull close and fast to the shoulder","Dip under, then stand tall"],"aka": ["one-arm barbell clean","single-arm barbell clean"]},"One-hand barbell jerk": {"what": "Driving a barbell from the shoulder to overhead with one hand using the legs, an old-time lift.","cues": ["Bar balanced at the shoulder","Dip and drive hard","Lock the arm, dip under and stand"],"aka": ["one-arm barbell jerk","one-hand jerk"]},"One-hand barbell snatch": {"what": "Lifting a barbell from the floor to overhead in one movement with one hand, an old-time lift.","cues": ["Centre grip, bar balanced","Pull close, drop under fast","Catch with the arm locked, stand tall"],"aka": ["one-arm barbell snatch","one-hand snatch"]},"Two-dumbbell clean and jerk": {"what": "Cleaning two dumbbells to the shoulders and jerking them overhead, an old-time lift; trains power and shoulders.","cues": ["Clean both bells to the shoulders together","Dip and drive hard","Lock both arms out overhead"],"aka": ["dumbbell clean and jerk","DB clean and jerk"]},"One-hand dumbbell swing": {"what": "Swinging a dumbbell with one hand from between the legs to overhead in one motion, an old-time lift.","cues": ["Hike the bell back between the legs","Snap the hips to drive it up","Lock out overhead, lower with control"],"aka": ["one-arm dumbbell swing","dumbbell swing"]},"Partner hand balancing": {"what": "Hand-to-hand and other balances on or supporting a partner; trains strength, balance and trust.","cues": ["Learn each balance with a spotter","Base stays stacked, arms locked","Top stays tight, move slowly"],"aka": ["acrobalance","hand-to-hand","acroyoga","adagio"]},"Front rack hold": {"what": "Holding a barbell or kettlebells in the front rack position; trains upper back, trunk and breathing under load.","cues": ["Elbows high, bar on the shoulders","Brace and breathe behind the brace","Stand tall, hold for time"],"aka": ["rack hold","front-rack carry"]},"Box jumps": {"what": "Jumping from the floor onto a box and stepping down; trains leg power.","cues": ["Swing the arms and jump up","Land softly in a quarter squat","Step down, don't jump down"],"aka": ["box jump","plyo box jump"]},"High jump": {"what": "Running and jumping over a raised bar, the athletics event; trains spring and coordination.","cues": ["Curve the run-up into the bar","Plant and drive the knee up","Arch over and land on the mat"],"aka": ["Fosbury flop","scissors jump"]},"Sledgehammer strikes": {"what": "Swinging a sledgehammer down onto a tyre or ground target; trains trunk, shoulders, grip and conditioning.","cues": ["Slide the top hand down as it falls","Strike with the hips and trunk","Alternate sides, watch the rebound"],"aka": ["sledgehammer swings","tyre slams","hammer strikes"]},"Shot put": {"what": "Pushing a heavy metal ball from the neck for distance, the athletics event; trains power.","cues": ["Shot tucked at the neck, elbow high","Drive from the back leg into the hips","Push it out, don't throw it"],"aka": ["shot","putting the shot"]},"Clean and press": {"what": "Cleaning a barbell to the shoulders, then pressing it overhead without leg drive; trains strength and power.","cues": ["Clean to the shoulders, elbows forward","Pause, brace, then press","Lower to the shoulders, then the floor"],"aka": ["clean & press","clean and military press"]},"Barrel lift": {"what": "Lifting a barrel from the floor, gripped by its rim or hugged; an old-time test of grip and whole-body strength.","cues": ["Start with an empty or light barrel","Set the grip before you lift","Lift with the legs, keep it close"],"aka": ["barrel lifting","chime lift","keg lift"]},"Long jump": {"what": "Sprinting down a runway and jumping as far as possible from a board, the athletics event.","cues": ["Build speed through the run-up","Hit the board and drive up","Swing the feet forward to land"],"aka": ["running long jump","broad jump"]},"Pole vault": {"what": "Sprinting with a long pole, planting it and swinging up over a high bar; trains speed, strength and body control.","cues": ["Learn with a coach and a full pit","Carry the pole high, plant early","Swing, extend and push off the pole"],"aka": ["vaulting","vault"]},"Hammer throw": {"what": "Spinning and throwing a metal ball on a wire from a circle, the athletics event; trains whole-body power.","cues": ["Wind the hammer round the head","Turn on the heels and toes, hips leading","Release with the arms long"],"aka": ["athletics hammer","hammer"]},"Discus throw": {"what": "Spinning and slinging a flat disc from a circle for distance, the athletics event; trains power and rotation.","cues": ["Disc against the fingertips, arm long","Turn through the circle, hips leading","Release with a flat, sweeping arm"],"aka": ["discus"]},"Javelin throw": {"what": "Running and throwing a spear for distance, the athletics event; trains speed and shoulder and trunk power.","cues": ["Carry the javelin high and relaxed","Crossover steps, then a firm plant","Pull through over the top, elbow high"],"aka": ["javelin","spear throw"]},"Track intervals": {"what": "Repeated runs over set distances on a track with timed recovery; builds speed and endurance.","cues": ["Warm up well before the first rep","Run each rep at an even pace","Keep the recoveries honest"],"aka": ["track repeats","interval training","intervals","400s"]},"Time trial": {"what": "Running, rowing or riding a set distance flat out against the clock; tests fitness.","cues": ["Warm up thoroughly first","Start steady, not flat out","Push hardest in the final stretch"],"aka": ["TT","test run"]},"Rowing": {"what": "Rowing on a machine or in a boat, legs driving then back and arms; trains the whole body and endurance.","cues": ["Legs, then hips, then arms","Arms, hips, then legs on the return","Keep the handle level and smooth"],"aka": ["erg","rowing machine","indoor rowing","row"]},"Running": {"what": "Running at a steady pace over distance; builds aerobic fitness and leg endurance.","cues": ["Tall posture, relaxed shoulders","Feet land under the body","Breathe steadily at a pace you can talk"],"aka": ["jogging","run","easy run","road running"]},"Hill repeats": {"what": "Running hard up a hill and walking or jogging back down, repeated; builds leg strength and fitness.","cues": ["Lean slightly into the hill","Drive the arms and knees","Jog or walk down to recover"],"aka": ["hill sprints","hill reps","hills"]},"Sprints": {"what": "Short, maximal-effort runs with full recovery between; trains speed and power.","cues": ["Warm up and build to full speed","Drive the arms, stay tall","Rest fully between reps"],"aka": ["sprint","sprinting","wind sprints","dashes"]},"Swimming": {"what": "Swimming laps in a pool or open water; trains endurance and the whole body.","cues": ["Long body, head in line","Breathe out under the water","Smooth, even strokes"],"aka": ["swim","laps","freestyle"]},"Board paddling": {"what": "Paddling a surf-lifesaving board by hand, lying or kneeling, as in Australian ironman racing; trains shoulders, back and endurance.","cues": ["Chest lifted, weight centred on the board","Reach long and pull through deep","Paddle in a steady, even rhythm"],"aka": ["paddleboarding","prone paddling","knee paddling","nipper board"]},"Surf ski paddling": {"what": "Paddling a long sit-on ocean kayak with a double-bladed paddle; trains back, trunk, shoulders and endurance.","cues": ["Sit tall, feet on the footrest","Rotate the trunk with each stroke","Push with the leg on the stroke side"],"aka": ["surf ski","ocean ski","ski paddling"]},"Jump rope": {"what": "Skipping over a turning rope; trains footwork, calves and conditioning.","cues": ["Turn the rope from the wrists","Small, light hops on the balls of the feet","Elbows close, stay relaxed"],"aka": ["skipping","skipping rope","jumping rope"]},"Loaded march": {"what": "Walking briskly over distance carrying a loaded pack; trains legs, back and endurance.","cues": ["Pack high and tight on the back","Brisk steps, stand tall","Build load and distance gradually"],"aka": ["rucking","ruck march","ruck","weighted hike"]},"Small-ball game": {"what": "A fast passing and intercepting ball game that Galen praised for training body and mind together.","cues": ["Stay light on the feet","Keep eyes on the ball and players","Move constantly, change direction often"],"aka": ["Galen's small ball","harpastum","ball game"]},"Fartlek": {"what": "Continuous running with unplanned bursts of faster pace, Swedish for 'speed play'; builds speed and endurance.","cues": ["Run easy between the bursts","Surge by feel, to a tree or post","Keep moving the whole session"],"aka": ["speed play"]},"Stride-outs": {"what": "Relaxed accelerations over about 80–100 m to near top speed; sharpen form and speed.","cues": ["Build up smoothly to near top speed","Stay tall and relaxed","Ease down, walk back to recover"],"aka": ["strides","stride outs","accelerations"]},"Sled sprints": {"what": "Sprinting while pulling or pushing a weighted sled; trains acceleration and leg power.","cues": ["Lean forward from the ankles","Drive hard with short, powerful steps","Keep the load light enough to sprint"],"aka": ["resisted sprints","sled pulls","prowler sprint"]},"High knees": {"what": "Running in place or forward, driving the knees up high; trains the hip flexors and sprint mechanics.","cues": ["Stay tall on the balls of the feet","Drive the knee to hip height","Quick, light contacts with the ground"],"aka": ["high knee drill","knee drives"]},"Straight-leg bounds": {"what": "Running with straight legs, pawing the ground under the hips; a sprint drill for the hamstrings.","cues": ["Legs nearly straight, toes up","Pull the foot down and back under you","Stay tall with quick, light contacts"],"aka": ["straight leg bounding","straight-leg runs","scissor runs"]},"Horse riding": {"what": "Riding a horse at a walk, trot, canter or gallop; trains the legs, trunk, posture and balance.","cues": ["Sit tall, heels down","Move with the horse from the hips","Light, steady hands on the reins"],"aka": ["riding","horseback riding","equestrian"]},"Uphill bounding": {"what": "Long, springy leaping strides up a slope; trains leg power and stride length.","cues": ["Drive the knee up and forward","Push off hard from the back foot","Land lightly and spring into the next"],"aka": ["hill bounds","uphill bounds"]},"Race walking": {"what": "Fast walking with one foot always on the ground and a straight front knee, the athletics event.","cues": ["Front leg straight from contact to upright","One foot on the ground at all times","Quick arm drive, hips rolling forward"],"aka": ["racewalking","race walk","speed walking"]},"Race-walk drills": {"what": "Technique drills for race walking, such as hip rolls and straight-leg walks; train the walking form.","cues": ["Move slowly through each drill","Keep the front knee straight on contact","Let the hips rotate forward"],"aka": ["racewalk drills","race walking drills"]},"Hill bounding": {"what": "Bounding up a hill in long, exaggerated strides, as in Lydiard's hill circuit; trains leg power and endurance.","cues": ["Exaggerate the knee lift and push-off","Land on the forefoot","Jog back down to recover"],"aka": ["hill bounds","Lydiard hill bounding"]},"Hill springing": {"what": "Springing up a hill on the balls of the feet with little forward travel, from Lydiard's hill circuit; trains ankles and calves.","cues": ["Short steps, high on the toes","Push hard from the ankles","Body tall, slow forward movement"],"aka": ["Lydiard hill springing","hill hops","springing"]},"Outrigger paddling": {"what": "Paddling an outrigger canoe with a single-bladed paddle, the va'a or waka ama of Polynesia; trains back, trunk and endurance.","cues": ["Sit tall, reach forward with the paddle","Rotate the trunk, pull past the hip","Keep in time with the crew"],"aka": ["va'a","waka ama","OC1","OC6","outrigger canoe"]},"Cycling": {"what": "Riding a bike on road, trail or an indoor trainer; builds aerobic fitness and leg endurance.","cues": ["Saddle set so the knee stays slightly bent","Smooth, round pedal strokes","Relaxed shoulders, light grip"],"aka": ["biking","bike","cycle","spin"]},"Jumping jacks": {"what": "Jumping the feet apart while swinging the arms overhead, then back together; a conditioning and warm-up drill.","cues": ["Land softly on the balls of the feet","Arms reach overhead as the feet go wide","Keep a steady rhythm"],"aka": ["star jumps","jumping jack","side-straddle hop"]},"Hurdles": {"what": "Sprinting over a row of barriers in stride, the athletics event; trains speed, mobility and rhythm.","cues": ["Attack the hurdle with the lead knee","Snap the trail leg through high","Keep sprinting between the barriers"],"aka": ["hurdling","hurdle drills","110m hurdles"]},"Tempo runs": {"what": "Runs at a steady, controlled, comfortably hard pace for a set time or distance; build endurance.","cues": ["Settle into a steady pace","Stay relaxed and controlled","Hold the pace, don't race it"],"aka": ["tempo","tempo running","threshold run"]},"Wrestling practice": {"what": "Live wrestling and drilling with a partner; trains strength, endurance and grappling skill.","cues": ["Warm up the neck and hips first","Stay low in your stance","Stop when a position isn't safe"],"aka": ["wrestling","grappling","freestyle wrestling"]},"Pahlavani wrestling": {"what": "Koshti pahlavani, Iran's traditional wrestling that closes a zurkhaneh session; trains strength, endurance and grappling.","cues": ["Low stance, hands working the arms","Grip and push from the legs","Stay balanced, wrestle with respect"],"aka": ["koshti pahlavani","koshti","Persian wrestling","zurkhaneh wrestling"]},"Pa zadan footwork": {"what": "The rhythmic stepping and stamping that opens a zurkhaneh session, done to the morshed's drum; trains legs and coordination.","cues": ["Keep time with the drum","Light, springy steps on the balls of the feet","Arms loose, body upright"],"aka": ["pa zadan","pazadan","zurkhaneh footwork"]},"Charkh spins": {"what": "Spinning in place with the arms out, a zurkhaneh drill often held for long sets; trains balance and focus.","cues": ["Arms out, palms open","Pivot on the ball of one foot","Start slow, stop if dizzy"],"aka": ["charkh","charkh zadan","zurkhaneh spinning"]},"Mallakhamb": {"what": "Holds, climbs and poses on an oiled wooden pole or hanging rope, from Indian wrestling; trains grip, strength and body control.","cues": ["Learn the basic grips and climbs first","Squeeze the pole with the thighs and arms","Move slowly into each pose"],"aka": ["mallakhamba","malkhamb","pole mallakhamb","rope mallakhamb"]},"Stick fighting": {"what": "Sparring or drilling strikes and blocks with sticks, as in many traditions worldwide; trains timing, footwork and conditioning.","cues": ["Wear protection for live work","Strike from the hips, not just the arm","Footwork first, keep moving"],"aka": ["arnis","eskrima","kali","bataireacht","canne de combat"]},"Oil wrestling": {"what": "Yağlı güreş, Turkey's traditional wrestling with both wrestlers coated in olive oil; trains grip, strength and endurance.","cues": ["Low stance, hands busy","Work for grips on the trunk and legs","Stay calm and breathe through the bout"],"aka": ["yağlı güreş","yagli gures","Turkish oil wrestling","Kırkpınar"]},"Peşrev": {"what": "The ritual warm-up before Turkish oil wrestling: slow steps, bows, knee slaps and stretches done together.","cues": ["Move slowly and together","Slap the knees and bend low","Use it to loosen the hips and shoulders"],"aka": ["pesrev","peshrev","oil wrestling warm-up"]},"Judo randori": {"what": "Free practice in judo, throwing and being thrown by a resisting partner; trains skill, strength and conditioning.","cues": ["Grip firmly, stay upright and mobile","Attack and defend at a controlled pace","Breakfall properly on every throw"],"aka": ["randori","judo sparring","free practice"]},"Jiu-jitsu drilling": {"what": "Repeating jiu-jitsu techniques with a cooperative partner; builds skill and conditioning.","cues": ["Drill slowly, then build speed","Partner gives light, steady resistance","Focus on one detail at a time"],"aka": ["BJJ drilling","jiu-jitsu drills","technique drilling"]},"Jiu-jitsu rolling": {"what": "Live sparring in jiu-jitsu with a resisting partner; trains skill, strength and endurance.","cues": ["Tap early, tap often","Breathe and stay calm under pressure","Roll at a pace you can keep"],"aka": ["rolling","BJJ sparring","live rolling","jiu-jitsu sparring"]},"Shrimping": {"what": "Pushing the hips away with the feet to slide sideways while lying down; a core grappling escape.","cues": ["On your side, push off one foot","Drive the hips back and away","Hands frame as the hips move"],"aka": ["hip escape","shrimp","shrimps"]},"Technical stand-up": {"what": "Standing up from the floor while keeping a guarded base; a grappling and self-defence movement.","cues": ["One hand posted behind, other guarding","Lift the hips and swing the leg back","Stand into a stance, hands up"],"aka": ["technical standup","technical lift","combat base stand-up"]},"Breakfalls": {"what": "Falling safely by rolling or slapping the mat to spread the impact; a core judo and grappling skill.","cues": ["Tuck the chin, head off the mat","Slap with the whole arm as you land","Start low and build height slowly"],"aka": ["ukemi","break falls","falling","rolls"]},"Capoeira roda": {"what": "The capoeira circle, two players moving together in the middle to music and song; trains agility and endurance.","cues": ["Keep the ginga moving","Watch your partner the whole time","Stay low and breathe"],"aka": ["roda","capoeira game","jogo"]},"Ginga": {"what": "Capoeira's base step, rocking side to side in a low triangle stance; trains legs, hips and conditioning.","cues": ["Step back in a triangle, staying low","Opposite arm guards the face","Keep a smooth, steady rhythm"],"aka": ["capoeira ginga","jinga"]},"Aú": {"what": "Capoeira's cartwheel, often done slowly with eyes on the partner; trains shoulders, balance and body control.","cues": ["Place the hands one after the other","Hips over the shoulders, legs wide","Look at your partner, not the floor"],"aka": ["au","capoeira cartwheel","cartwheel"]},"Meia lua de frente": {"what": "A capoeira kick sweeping the straight leg in an arc in front of the body; trains the hips and balance.","cues": ["Leg stays straight through the arc","Swing from outside to inside","Guard up, return to the ginga"],"aka": ["front half moon kick","meia-lua de frente","inside crescent kick"]},"Meia lua de compasso": {"what": "A low spinning capoeira kick with hands on the floor, the heel sweeping round in a wide arc; trains hips, trunk and power.","cues": ["Hands down, look through the legs","Turn the hips to drive the heel round","Keep the kicking leg long"],"aka": ["compasso","rabo de arraia","spinning heel kick"]},"Armada": {"what": "A standing capoeira spinning kick, the straight leg swinging round in an outward arc; trains the hips and balance.","cues": ["Turn the head and shoulders first","Swing the leg straight and wide","Land back in the ginga"],"aka": ["armada kick","spinning outside crescent kick"]},"Esquiva": {"what": "A capoeira dodge, dropping low or leaning away to slip a kick; trains the legs and reflexes.","cues": ["Drop low, weight on the legs","Arm guards the face","Eyes stay on the partner"],"aka": ["capoeira dodge","esquivas"]},"Negativa": {"what": "A low capoeira escape, sinking to the floor on one bent leg with the other stretched out; trains legs and mobility.","cues": ["Sink onto one bent leg, other long","One hand down, the other guards the face","Rise or roll out smoothly"],"aka": ["negativa de Angola","capoeira floor escape"]},"Capoeira sequences": {"what": "Set partner drills of attacks and escapes, such as Mestre Bimba's sequências; build capoeira skill and conditioning.","cues": ["Learn each move slowly first","Flow from one move into the next","Keep the ginga between movements"],"aka": ["sequências","sequencias","Bimba sequences"]},"Palus drill": {"what": "Striking and thrusting at a wooden post with a weighted practice sword, the Roman recruit's drill.","cues": ["Shield up, side-on to the post","Strike or thrust, then recover the guard","Move the feet with each attack"],"aka": ["palus","pell","pell drill","post drill"]},"Shadow boxing": {"what": "Throwing punches and moving around without a partner or bag; trains technique, footwork and conditioning.","cues": ["Guard up, chin down","Turn the hips into each punch","Move the feet between combinations"],"aka": ["shadowboxing","shadow sparring"]},"Shiko": {"what": "Sumo's leg-raising stomp: lift one leg high to the side, then plant it into a deep squat; trains hips, legs and balance.","cues": ["Wide stance, toes out, sink low first","Shift onto one leg and raise the other","Stamp it down and sink back low"],"aka": ["shiko-fumi","shikofumi","sumo stomp"]},"Koshiwari": {"what": "Sumo's deep, wide squat held with the back upright; trains the hips, thighs and posture.","cues": ["Wide stance, toes turned out","Sink until the thighs are near level","Push the knees out, back upright"],"aka": ["koshi-wari","sumo squat","sumo stance"]},"Matawari": {"what": "Sumo's straddle split, sitting with legs wide and leaning the chest toward the floor; trains hip and groin flexibility.","cues": ["Sit tall, legs wide apart","Lean forward from the hips","Ease in gradually, never force it"],"aka": ["mata-wari","sumo split","straddle split","middle split"]},"Suriashi": {"what": "Sumo's sliding walk in a low stance, the feet never leaving the ground; trains legs, hips and balance.","cues": ["Low stance, hips sunk","Slide the feet, never lift them","Hands forward, push from the back foot"],"aka": ["suri-ashi","sumo walk","sliding steps"]},"Teppo": {"what": "Sumo's palm-thrusting drill against a wooden pole; trains pushing, shoulders and coordinated footwork.","cues": ["Low stance, hands at chest height","Thrust with the palm as the same-side foot steps","Drive from the legs, elbows in"],"aka": ["teppo bashira","pole thrusts","tsuppari practice"]},"Butsukari-geiko": {"what": "Sumo pushing practice, one wrestler driving another across the ring; trains pushing power and endurance.","cues": ["Head low, hands on the partner's chest","Push from the legs with suriashi steps","Partner rolls out when you finish"],"aka": ["butsukari","sumo pushing drill"]},"Uchikomi": {"what": "Repeating a judo throw's entry and fit with a partner, without throwing; builds technique and conditioning.","cues": ["Grip, step in and fit the throw","Load the partner but don't throw","Repeat fast with good form"],"aka": ["uchi-komi","entry drill","fit-ins"]},"Makiwara": {"what": "Striking a padded post fixed in the ground, from karate; trains punching power and alignment.","cues": ["Start with light strikes","Wrist straight, hit with the first two knuckles","Drive from the hips, pull back fast"],"aka": ["makiwara striking","striking post","punching post"]},"Chi-ishi": {"what": "A karate hojo undo tool, a stone or concrete weight on a wooden handle, levered and rotated; trains grip, wrists and shoulders.","cues": ["Grip the end of the handle","Rotate and lever slowly, wrist strong","Keep the elbow and shoulder steady"],"aka": ["chiishi","hojo undo","strength stone"]},"Nigiri-game": {"what": "Karate's clay gripping jars, held by the rim and carried through deep stances, loaded as strength grows; trains grip and legs.","cues": ["Grip the rim with the fingertips","Walk slowly in a low stance","Start empty, add sand or stones gradually"],"aka": ["nigiri game","gripping jars","hojo undo jars"]},"Ishi-sashi": {"what": "A stone hand weight shaped like a padlock, gripped and swung, flipped or pressed; a karate tool for grip and forearms.","cues": ["Grip the handle firmly","Move it slowly, then add speed","Keep the wrist straight and strong"],"aka": ["ishisashi","stone padlock","stone lock"]},"Kongoken": {"what": "A large oval iron ring lifted, pressed and rolled around the body, added to Goju-ryu karate training; trains the whole body.","cues": ["Grip the ring at shoulder width","Move it slowly through each pattern","Keep the trunk braced and upright"],"aka": ["kongo-ken","iron ring"]},"Eagle dance": {"what": "The Mongolian wrestler's ritual dance, arms spread and lifted slowly like wings; loosens the shoulders and legs.","cues": ["Spread the arms wide like wings","Step slowly, lifting the knees","Breathe deep, move with control"],"aka": ["devekh","deveekh","Mongolian eagle dance"]},"Archery": {"what": "Shooting a bow at a target; trains the back, shoulders, focus and steady breathing.","cues": ["Stand side-on, feet steady","Draw with the back, not just the arm","Release smoothly and follow through"],"aka": ["bow shooting","traditional archery","kyudo","gungdo"]},"Footwork drills": {"what": "Moving in, out and around in a fighting stance, often on a ladder or lines; trains footwork and conditioning.","cues": ["Stay on the balls of the feet","Small steps, keep the stance","Hands up as you move"],"aka": ["footwork","agility ladder","stance drills"]},"Sparring": {"what": "Controlled live practice with a partner in a striking art; trains timing, defence and conditioning.","cues": ["Agree the pace with your partner","Wear protective gear","Keep the hands up and breathe"],"aka": ["light sparring","kumite","sparring session"]},"Jacket wrestling": {"what": "Wrestling while gripping a jacket, as in Georgia's chidaoba, judo or sambo; trains grip, pulling strength and throws.","cues": ["Grip the jacket firmly","Break the partner's balance first","Stay low and breathe"],"aka": ["chidaoba","sambo","jacket grappling"]},"Heavy bag": {"what": "Punching or kicking a heavy hanging bag; trains power, technique and conditioning.","cues": ["Wrap the hands, wrists straight","Turn the hips into each strike","Stay in range and keep moving"],"aka": ["bag work","punching bag","heavy bag work"]},"Mitt work": {"what": "Hitting focus mitts held by a partner who calls combinations; trains speed, accuracy and conditioning.","cues": ["Hit the centre of the mitt","Return the hands to the guard","Stay relaxed between combinations"],"aka": ["pad work","focus mitts","mitts"]},"Belt wrestling": {"what": "Wrestling while gripping a belt or band round the opponent, as in Korean ssireum or Central Asian kurash; trains strength and throws.","cues": ["Firm grip on the belt","Stay low, chest close","Lift and turn with the legs and hips"],"aka": ["ssireum","kurash","kuresh","alysh"]},"Forms practice": {"what": "Practising set sequences of techniques, such as karate kata or taekwondo poomsae; trains technique and stamina.","cues": ["Learn the pattern slowly first","Crisp techniques from stable stances","Breathe in time with the movement"],"aka": ["kata","poomsae","hyung","taolu","patterns"]},"Pad kicks": {"what": "Kicking pads or shields held by a partner; trains kicking power, accuracy and conditioning.","cues": ["Pivot on the standing foot","Turn the hips over into the kick","Guard up, recover the leg fast"],"aka": ["kick pads","Thai pads","pad work"]},"Full-draw holds": {"what": "Holding a bow at full draw without an arrow, as in Korean archery training; trains back and shoulder strength.","cues": ["Use a bow you can draw with control","Hold steady at full draw","Let down slowly, never dry-fire"],"aka": ["SPT holds","bow holds","draw holds"]},"Speed bag": {"what": "Punching a small rebounding bag in rhythm; trains hand speed, timing and shoulder endurance.","cues": ["Bag at about mouth height","Hit in small circles, let it rebound","Keep a steady rhythm, hands up"],"aka": ["speed ball","speedbag"]},"Calf raises": {"what": "Rising onto the balls of the feet and lowering under control; trains the calves.","aka": ["calf raise","standing calf raise","heel raise"]},"Seated calf raise": {"what": "Raising the heels against a weighted pad on the knees while seated; trains the soleus.","aka": ["seated calf","bent-knee calf raise"]},"Donkey calf raise": {"what": "A calf raise bent over at the hips, with weight on the hips or a machine; trains the calves in a stretch.","cues": ["Hinge forward, back flat, hands supported","Rise high onto the balls of the feet","Lower slowly to a full stretch"],"aka": ["donkey calf","donkey raises"]},"Leg press calf raise": {"what": "Pushing the leg press sled with the balls of the feet; trains the calves.","cues": ["Balls of the feet on the platform edge","Legs nearly straight, knees soft","Press through the toes, lower slowly"],"aka": ["calf press","leg press calf press"]},"Isometric rack calf raise": {"what": "Rising on the toes against a bar fixed under power-rack pins and holding; trains calf strength.","cues": ["Bar on the back, pins just above it","Rise hard onto the toes into the pins","Hold 6–12 seconds, then ease down"],"aka": ["isometric calf raise","rack toe raise"]},"Barbell straddle hop": {"what": "Hopping the feet apart and together with a light bar across the shoulders, an old-time drill; trains calves and spring.","cues": ["Light bar on the upper back","Hop on the balls of the feet","Small, quick hops, land softly"],"aka": ["straddle hop","straddle jump","barbell jumping jack"]},"Tibialis raises": {"what": "Leaning against a wall with heels out front and lifting the toes; trains the shins.","aka": ["tib raise","tibialis raise","toe raise","tib bar"]},"FHL calf raise": {"what": "A calf raise pushing through the big toe; trains the flexor hallucis longus and the foot.","aka": ["big toe calf raise","flexor hallucis longus raise"]},"KOT calf raise": {"what": "A calf raise with the knees bent forward over the toes; trains the calves through a deep ankle range.","aka": ["knees over toes calf raise","bent-knee calf raise"]},"Soleus raise": {"what": "A calf raise with the knees kept bent throughout; trains the soleus.","aka": ["soleus calf raise","bent-knee calf raise"]},"Single-leg calf raise": {"what": "A calf raise on one foot at a time; trains each calf on its own.","aka": ["one-leg calf raise","SL calf raise"]},"Patrick step": {"what": "A slow step-down from a low step with the knee travelling forward over the toes; trains the knees and quads.","aka": ["Patrick step-down","ATG step-down"]},"Poliquin step-up": {"what": "A step-up with the working heel raised on a slant and the knee driving forward; trains the quads around the knee.","aka": ["Poliquin step","VMO step-up"]},"Petersen step-up": {"what": "A step-up with the working heel lifted and the knee travelling over the toes; trains the quads and knee.","aka": ["Peterson step-up","Petersen step"]},"Slant step-down": {"what": "Lowering the free heel from a slant or step on one leg, knee travelling forward; trains the quads and knee.","aka": ["slant board step-down","step-down"]},"Slant board steps": {"what": "Slow steps on a slant board with the heels higher than the toes; trains the knees, quads and ankles.","aka": ["slant steps","slant board step-up"]},"ATG split squat": {"what": "A long-stride split squat with the front knee far over the toes and the back knee low; trains knees, quads and hips.","aka": ["knees over toes split squat","KOT split squat","full split squat"]},"KOT squat": {"what": "A deep squat with the heels raised so the knees travel past the toes; trains the quads and knees.","aka": ["knees over toes squat","heels-elevated squat"]},"Slant board squats": {"what": "A squat with the heels raised on a slant board; trains the quads through a deep knee bend.","aka": ["slant squat","slant board squat","heel-elevated squat"]},"ATG squat": {"what": "A full-depth squat, hips down to the heels; trains the legs and deep knee and ankle range.","aka": ["ass to grass squat","full squat","deep squat"]},"Sissy squat": {"what": "Leaning back as the knees travel forward and down with the heels raised; trains the quads.","aka": ["sissy squats"]},"Reverse Nordic": {"what": "Kneeling and leaning back in one line from knees to head; trains the quads and hip flexors.","aka": ["reverse Nordic curl","kneeling quad lean"]},"Reverse squat": {"what": "Lying on the back and pulling the knees to the chest against a band or cable, a squat in reverse; trains the hip flexors.","cues": ["Lie on the back, band around the feet","Pull the knees in toward the chest","Return slowly to straight legs"],"aka": ["ATG reverse squat","lying hip flexor pull"]},"Nordic curls": {"what": "Kneeling with the ankles anchored and lowering the body forward slowly; trains the hamstrings.","aka": ["Nordic hamstring curl","Nordics","NHC","Russian curl"]},"Hamstring roller": {"what": "Lying on the back with the heels on a roller, lifting the hips and curling the heels in; trains the hamstrings.","aka": ["roller leg curl","sliding leg curl","ball leg curl"]},"ATG RDL": {"what": "A Romanian deadlift taken down to a deep hamstring stretch; trains hamstrings and glutes through full range.","aka": ["full-stretch RDL","ATG Romanian deadlift"]},"Seated DB deadlift": {"what": "Sitting on a bench and rolling down to lower a dumbbell between the feet; trains back and hamstrings through range.","aka": ["seated dumbbell deadlift","seated Jefferson curl"]},"Elephant walk": {"what": "Folded forward with hands toward the floor, straightening one knee then the other; stretches the hamstrings.","aka": ["elephant walks"]},"Jefferson curl": {"what": "Rolling down one vertebra at a time holding a light weight, then rolling back up; trains spinal flexibility and hamstrings.","aka": ["Jefferson curls","spinal curl"]},"Seated good morning": {"what": "A good-morning hinge done sitting on a bench with a bar on the back; trains lower back and adductors.","aka": ["seated GM"]},"Single-leg back extension": {"what": "A back extension with only one leg anchored; trains each hamstring and glute on its own.","aka": ["one-leg back extension","single-leg hyper"]},"QL extension": {"what": "Lying sideways on a back-extension bench, bending down to the side and lifting back up; trains the quadratus lumborum.","aka": ["side back extension","lateral hyperextension","quadratus lumborum raise"]},"Cossack squat": {"what": "A side-to-side squat onto one leg with the other straight; trains the legs and groin mobility.","aka": ["side squat","lateral squat","cossack"]},"Standing pancake pulse": {"what": "A wide-stance forward fold with small, gentle pulses; stretches the groin and hamstrings.","aka": ["pancake stretch","standing pancake","straddle fold"]},"Couch stretch": {"what": "A kneeling stretch with the back shin up a wall or couch; opens the quads and hip flexors.","aka": ["quad stretch","hip flexor stretch","couch stretch pulse"]},"Piriformis stretch": {"what": "Lying on the back with one ankle over the other knee, drawing the legs in; stretches the deep hip.","aka": ["figure-four stretch","figure 4 stretch"]},"Pigeon push-up": {"what": "From a pigeon stretch, pressing up through the hands and lowering back into it; a loaded stretch for the hips.","cues": ["Front shin across, back leg long","Push up through the hands","Lower slowly back into the stretch"],"aka": ["pigeon pushup","pigeon pulse"]},"Pigeon pose": {"what": "A hip stretch with the front shin angled across and the back leg long behind.","aka": ["pigeon stretch","eka pada rajakapotasana"]},"Slant toe touch": {"what": "Standing with the toes raised on a slant board and folding to touch them; stretches the hamstrings and calves.","cues": ["Toes up on the slant, heels down","Soft knees, fold from the hips","Reach for the toes, breathe, return"],"aka": ["slant board toe touch","toes-elevated toe touch"]},"L-sit": {"what": "Holding the legs straight out in front while supported on the hands; trains abs, hip flexors and triceps.","aka": ["L sit","L-hold"]},"Full knee raise": {"what": "Hanging and lifting the knees as high as they go; trains the abs and hip flexors.","aka": ["full-range knee raise","hanging knee raise"]},"Hanging leg raise": {"what": "Hanging from a bar and raising straight legs; trains the abs and hip flexors.","aka": ["HLR","straight-leg raise","hanging straight leg raise"]},"Garhammer raise": {"what": "Hanging and pulling the knees high to the chest as the hips curl up; trains the abs.","aka": ["Garhammer","hanging Garhammer"]},"Powell raise": {"what": "Lying on one side and raising a light dumbbell from in front of the body up and out; trains rear delts and rotator cuff.","cues": ["Lie on the side, bell in the top hand","Lift the bell up and out to vertical","Very light, slow and controlled"],"aka": ["side-lying rear delt raise","side-lying lateral raise"]},"External rotation": {"what": "Rotating the forearm outward with the elbow tucked at the side; trains the rotator cuff.","aka": ["shoulder external rotation","ER","cable external rotation","band external rotation"]},"Trap 3 raise": {"what": "Raising the arm diagonally overhead, thumb up, while leaning forward; trains the lower traps.","aka": ["Y raise","lower trap raise","trap-3"]},"Ring face pull": {"what": "A bodyweight face pull leaning back on gymnastics rings; trains the rear delts and upper back.","aka": ["ring face pulls","TRX face pull"]},"Cross bench pullover": {"what": "Lying across a bench, lowering a weight behind the head and pulling it over the chest; trains lats, chest and rib cage.","aka": ["cross-bench dumbbell pullover","pullover"]},"ATG shoulder press": {"what": "A full-range overhead press from a deep bottom position to full lockout; trains shoulders and triceps.","aka": ["full-range shoulder press"]},"ATG dip": {"what": "A dip lowered to a deep, controlled stretch; trains chest, triceps and shoulder range.","aka": ["deep dip","full-range dip"]},"ATG chin-up": {"what": "A chin-up from a full dead hang to the top; trains lats and biceps through full range.","aka": ["full-range chin-up"]},"Backward sled drag": {"what": "Walking backward while pulling a sled; trains the quads and knees.","aka": ["reverse sled drag","backward drag","sled pull backwards"]},"Forward sled push": {"what": "Driving a weighted sled forward with the arms extended; trains the legs and conditioning.","aka": ["sled push","prowler push"]},"Backward walk": {"what": "Walking backward on the toes; trains the quads and knees.","aka": ["reverse walking","retro walking","backwards walking"]},"Backward step-up": {"what": "Stepping up backwards onto a low step with the knee forward over the toes; trains the quads and knees.","cues": ["Stand with your back to a low step","Reach back with the toes and step up","Drive through the front of the foot"],"aka": ["reverse step-up","back step-up"]},"Band squat": {"what": "A squat standing on a resistance band with the handles at the shoulders; trains quads and glutes.","aka": ["banded squat","resistance band squat"]},"Band deadlift": {"what": "A deadlift standing on a resistance band; trains glutes, hamstrings and back.","aka": ["banded deadlift","resistance band deadlift"]},"Band Romanian deadlift": {"what": "A Romanian deadlift standing on a resistance band; trains the hamstrings and glutes.","aka": ["band RDL","banded RDL"]},"Band good morning": {"what": "A good-morning hinge with a band under the feet and over the neck; trains hamstrings and lower back.","aka": ["banded good morning"]},"Band lateral walk": {"what": "Side steps with a band around the legs in a slight squat; trains the side glutes.","aka": ["monster walk","lateral band walk","band side steps","crab walk"]},"Band glute kickback": {"what": "Pushing one heel back against a band; trains the glutes.","aka": ["banded kickback","glute kickback","donkey kick"]},"Band chest press": {"what": "Pressing forward against a band anchored behind you; trains chest, shoulders and triceps.","aka": ["banded chest press","band push"]},"Band overhead press": {"what": "Pressing overhead against a band anchored under the feet; trains shoulders and triceps.","aka": ["band shoulder press","banded overhead press","band OHP"]},"Band row": {"what": "Rowing the hands toward the ribs against a band anchored in front; trains the upper back.","aka": ["banded row","resistance band row"]},"Band lat pulldown": {"what": "Pulling a high-anchored band down with the elbows to the sides; trains the lats.","aka": ["band pulldown","banded lat pulldown"]},"Band pull-aparts": {"what": "Pulling a band apart in front of the chest with straight arms; trains rear delts and upper back.","aka": ["pull-aparts","band pull apart"]},"Band face pull": {"what": "Pulling a band from face height toward the face with the elbows high; trains rear delts and upper back.","aka": ["banded face pull"]},"Band bicep curl": {"what": "Curling against a band anchored under the feet; trains the biceps.","aka": ["band curl","banded curl"]},"Band tricep pushdown": {"what": "Pushing a high-anchored band down with the elbows pinned; trains the triceps.","aka": ["band pushdown","banded pushdown"]},"Band Pallof press": {"what": "Pressing a side-anchored band straight out while resisting the twist; trains the trunk.","aka": ["banded Pallof press","band anti-rotation press"]},"Band woodchop": {"what": "Pulling a band diagonally across the body with a turn of the trunk; trains the obliques.","aka": ["banded woodchop","band chop"]}};
